// Des: Plan and approval list: phrases to flow items, risk class from code, approve all or some once
// Flo: item text > job + words > risk (ask for group, forward) > saved as flow items > one printed list > approve ids or all
// I/O: item texts + Stor (caller) > flow id, list text, approvals saved
// ===================================================================
const std = @import("std"); const data = @import("st-stat-data.zig"); const flo = @import("st-flow-data.zig"); const jobs = @import("ru-jobs-main.zig"); const rec = @import("ru-reci-main.zig");
const SEP = "\x1f";
pub const Parsed = struct { job: []const u8, args: []const []const u8 };
pub fn riskOf(job: []const u8) []const u8 { if (std.mem.eql(u8, job, "group") or std.mem.eql(u8, job, "forward")) return "ask"; return "low"; }
pub fn parseItem(aren: std.mem.Allocator, text: []const u8) !Parsed { const trm = std.mem.trim(u8, text, " \r\n\t"); if (trm.len == 0) return error.BadJob; var itr = std.mem.tokenizeScalar(u8, trm, ' '); const first = itr.next() orelse return error.BadJob; if (jobs.known(first) and !std.mem.eql(u8, first, "say")) { var words: std.ArrayList([]const u8) = .empty; while (itr.next()) |wrd| try words.append(aren, wrd); return .{ .job = first, .args = words.items }; } const body = if (std.mem.eql(u8, first, "say")) std.mem.trim(u8, trm[3..], " ") else trm; _ = rec.parse(body) catch return error.BadJob; const arr = try aren.alloc([]const u8, 1); arr[0] = body; return .{ .job = "say", .args = arr }; }
pub fn pack(aren: std.mem.Allocator, words: []const []const u8) ![]u8 { return std.mem.join(aren, SEP, words); }
pub fn unpack(aren: std.mem.Allocator, text: []const u8) ![]const []const u8 { var out: std.ArrayList([]const u8) = .empty; if (text.len == 0) return out.items; var itr = std.mem.splitSequence(u8, text, SEP); while (itr.next()) |wrd| try out.append(aren, wrd); return out.items; }
pub fn planFlow(sto: *data.Stor, aren: std.mem.Allocator, uuid: []const u8, name: []const u8, texts: []const []const u8, now_ms: i64) !i64 { if (texts.len == 0) return error.BadJob; var items: std.ArrayList(Parsed) = .empty; for (texts) |txt| try items.append(aren, try parseItem(aren, txt)); const fl = try flo.flowNew(sto, uuid, name, now_ms); var seq: i64 = 1; for (items.items) |itm| { _ = try flo.itemAdd(sto, fl, seq, itm.job, try pack(aren, itm.args), riskOf(itm.job), now_ms); seq += 1; } return fl; }
pub fn render(sto: *data.Stor, aren: std.mem.Allocator, flow: i64) ![]u8 { const its = try flo.itemsOf(sto, aren, flow); var out: std.ArrayList(u8) = .empty; var ask: u32 = 0; for (its) |itm| { const words = try unpack(aren, itm.args); const flat = try std.mem.join(aren, " ", words); const tag = if (itm.appr) "ok" else "NEEDS APPROVAL"; if (!itm.appr) ask += 1; try out.appendSlice(aren, try std.fmt.allocPrint(aren, "{d}. [{s}] {s} {s} ({s})\n", .{ itm.id, tag, itm.job, flat, itm.state })); } try out.appendSlice(aren, if (ask == 0) "nothing needs approval\n" else try std.fmt.allocPrint(aren, "{d} item(s) need approval: run 'za approve all' or 'za approve <ids>'; unapproved items are skipped\n", .{ask})); return out.items; }
pub fn parseIds(aren: std.mem.Allocator, text: []const u8) ![]i64 { var out: std.ArrayList(i64) = .empty; var itr = std.mem.tokenizeAny(u8, text, ", "); while (itr.next()) |tok| { const num = std.fmt.parseInt(i64, tok, 10) catch return error.BadJob; if (num <= 0) return error.BadJob; try out.append(aren, num); } if (out.items.len == 0) return error.BadJob; return out.items; }
pub fn approve(sto: *data.Stor, aren: std.mem.Allocator, flow: i64, what: []const u8) !u32 { if (std.ascii.eqlIgnoreCase(std.mem.trim(u8, what, " "), "all")) return flo.approveAll(sto, flow); const ids = try parseIds(aren, what); const its = try flo.itemsOf(sto, aren, flow); var cnt: u32 = 0; for (ids) |idz| { var mine = false; for (its) |itm| { if (itm.id == idz) mine = true; } if (!mine) return error.BadJob; if (try flo.itemApprove(sto, idz)) cnt += 1; } return cnt; }
